function startPractice(id,onComplete=null,scope=state.recall.scope,index=null,trial=null){const card=cards.find(function byID(c){return c.id===id;/* Code by Daniel using ChatGPT November 20, 2026 */});if(!card)return;const units=trial?[{label:trial[1],text:trial[2]+' '+trial[3]}]:state.recall.difficulty==='hard'?Road.units({...card,text:verseDisplay09(card)},scope):practiceUnits09(card,scope),counts=units.map(function unitCount(u,n){return state.recalls[recallKey(card,scope,n)]||0;/* Code by Daniel using ChatGPT November 20, 2026 */}),i=index===null?counts.indexOf(Math.min(...counts)):index,unit=units[Math.min(i,units.length-1)],count=state.recalls[recallKey(card,scope,i)]||0,halves=trial?[trial[2],trial[3]]:naturalHalves09(unit.text),opening=trial?!!trial[4]:count%2===1,target=opening?halves[0]:halves[1],cue=opening?halves[1]:halves[0],extras=cards.filter(function other(c){return c.id!==id;/* Code by Daniel using ChatGPT November 20, 2026 */}).map(function distractor(c){return plain(c.summary);/* Code by Daniel using ChatGPT November 20, 2026 */}),puzzle=Exploration.puzzle(target,state.recall.difficulty==='hard',extras);g.exercise={trial,id,scope,index:i,unit,opening,target,cue,parts:puzzle.parts,pool:puzzle.pool,selected:[],answer:'',done:false,helped:false,onComplete};practiceView();/* Code by Daniel using ChatGPT November 20, 2026 *//* Code by Daniel using ChatGPT November 20, 2026 */}
function practiceView(message=''){const ex=g.exercise;if(!ex)return;const c=cards.find(function current(card){return card.id===ex.id;/* Code by Daniel using ChatGPT November 11, 2026 */}),mode=state.recall.mode;let ui='';if(mode==='phrases'){ui=`<div class="recall-slot">${ex.selected.map(function selected(n){return escapeHTML(ex.pool.find(function tile(p){return p.n===n;/* Code by Daniel using ChatGPT November 11, 2026 */})?.text||'');/* Code by Daniel using ChatGPT November 11, 2026 */}).join(' ')||'Choose the missing phrases in order.'}</div><div class="recall-tiles">${ex.pool.map(function tile(p){return `<button data-pick="${p.n}" ${ex.selected.includes(p.n)?'disabled':''}>${escapeHTML(p.text)}</button>`;/* Code by Daniel using ChatGPT November 11, 2026 */}).join('')}</div><div class="row"><button id="recall-undo">Undo last</button><button class="primary" id="recall-check">Check the words</button></div>`;}else if(mode==='type'){ui='<label for="recall-answer">Type the missing half</label><textarea id="recall-answer" spellcheck="false" autocapitalize="off"></textarea><p>Punctuation, spacing, and capitalization are ignored.</p><button class="primary" id="recall-check">Check the words</button>';}else{if(!ex.options){const choices=cards.filter(function other(v){return v.id!==c.id;/* Code by Daniel using ChatGPT November 11, 2026 */}).slice(0,state.recall.difficulty==='hard'?7:3).map(function otherHalf(v){return Road.halves(Road.units(v,ex.scope)[0].text)[ex.opening?0:1];/* Code by Daniel using ChatGPT November 11, 2026 */});ex.options=Road.shuffle([...new Set([ex.target,...choices])]);}ui='<div class="collection-list">'+ex.options.map(function option(t,i){return `<button data-completion="${i}">${escapeHTML(t)}</button>`;/* Code by Daniel using ChatGPT November 11, 2026 */}).join('')+'</div>';}
showPanel(`<p class="verse-meta">${escapeHTML(verseReference(c))} · ${escapeHTML(ex.unit.label)}</p><h2 id="panel-title" class="action-prompt">${ex.trial?'Keep a firm hold · remember the next words':'Carry the words a little further'}</h2>${verseSpeaker09(c)}<p>${ex.opening?'Supply the opening before these words.':'Complete the second half after these words.'} There is no timer.</p><blockquote>${escapeHTML(ex.cue)}</blockquote>${ui}${scriptureContextHTML(c)}<p class="feedback" ${message?'':'hidden'}>${escapeHTML(message)}</p><div class="row"><button id="recall-help">Read together</button><button id="recall-difficulty">${state.recall.difficulty==='easy'?'Try harder choices':'Use easier phrases'}</button><button id="recall-leave">Back to exploring</button></div>`,'OPTIONAL HALF-CARD PRACTICE');
if(mode==='type'){$('#recall-answer').value=ex.answer;$('#recall-answer').oninput=function rememberAnswer(e){ex.answer=e.target.value;/* Code by Daniel using ChatGPT November 11, 2026 */};}panel.querySelectorAll('[data-pick]').forEach(function wireTile(b){b.onclick=function pickTile(){ex.selected.push(Number(b.dataset.pick));practiceView();/* Code by Daniel using ChatGPT November 11, 2026 */};/* Code by Daniel using ChatGPT November 11, 2026 */});panel.querySelectorAll('[data-completion]').forEach(function wireOption(b){b.onclick=function chooseCompletion(){checkPractice(ex.options[Number(b.dataset.completion)]);/* Code by Daniel using ChatGPT November 11, 2026 */};/* Code by Daniel using ChatGPT November 11, 2026 */});if($('#recall-check'))$('#recall-check').onclick=function checkRecall(){checkPractice(mode==='type'?ex.answer:ex.selected.map(function word(n){return ex.pool.find(function tile(p){return p.n===n;/* Code by Daniel using ChatGPT November 11, 2026 */}).text;/* Code by Daniel using ChatGPT November 11, 2026 */}).join(' '));/* Code by Daniel using ChatGPT November 11, 2026 */};if($('#recall-undo'))$('#recall-undo').onclick=function undo(){ex.selected.pop();practiceView();/* Code by Daniel using ChatGPT November 11, 2026 */};$('#recall-help').onclick=function help(){ex.helped=true;showPanel(`<h2 id="panel-title">Read the words together</h2><blockquote>${escapeHTML(ex.trial?ex.unit.text:verseDisplay09({...c,text:ex.unit.text}))}</blockquote><p>${escapeHTML(verseReference(c))}</p>${scriptureContextHTML(c)}<button class="primary" id="recall-return">Try with these words in mind</button><button id="recall-read-along">Continue with read-along help</button>`,'THE WORD BEFORE THE EXERCISE');$('#recall-return').onclick=function returnToPractice(){practiceView();/* Code by Daniel using ChatGPT November 11, 2026 */};$('#recall-read-along').onclick=function readAlong(){completePractice(true);/* Code by Daniel using ChatGPT November 11, 2026 */};/* Code by Daniel using ChatGPT November 11, 2026 */};$('#recall-difficulty').onclick=function difficulty(){state.recall.difficulty=state.recall.difficulty==='easy'?'hard':'easy';save();startPractice(ex.id,ex.onComplete,ex.scope,ex.index,ex.trial);/* Code by Daniel using ChatGPT November 11, 2026 */};$('#recall-leave').onclick=closePanel;/* Code by Daniel using ChatGPT November 11, 2026 *//* Code by Daniel using ChatGPT November 12, 2026 */}
function checkPractice(answer){const ex=g.exercise;if(!ex||ex.done)return false;if(Road.normalize(answer)!==Road.normalize(ex.target)){practiceView('Not quite. Read together, rearrange the phrases, or take another try.');return false;}completePractice(false);return true;/* Code by Daniel using ChatGPT November 11, 2026 */}
function completePractice(readAlong){const ex=g.exercise;if(!ex||ex.done)return;ex.done=true;const c=cards.find(function current(card){return card.id===ex.id;/* Code by Daniel using ChatGPT November 11, 2026 */});state.recalls[recallKey(c,ex.scope,ex.index)]=(state.recalls[recallKey(c,ex.scope,ex.index)]||0)+1;save();showPanel(`<h2 id="panel-title">${readAlong?'Read and carried together':'A little more of the Word remembered'}</h2><blockquote>${escapeHTML(ex.trial?ex.unit.text:verseDisplay09({...c,text:ex.unit.text}))}</blockquote><p>${escapeHTML(verseReference(c))}</p>${scriptureContextHTML(c)}<p>Next time, rehearse the other half. Rehearsing is a way to attend to the words; it does not measure your faith.</p>${rehearseMoreHTML(ex,c)}<button class="primary" id="recall-done">${ex.onComplete?'Continue the story':'Back to exploring'}</button>`,'WORDS TO KEEP');const complete=ex.onComplete;wireRehearseMore(ex,c);$('#recall-done').onclick=function finishRecall(){g.exercise=null;if(complete)complete();else closePanel();/* Code by Daniel using ChatGPT November 11, 2026 */};/* Code by Daniel using ChatGPT November 11, 2026 *//* Code by Daniel using ChatGPT November 12, 2026 */}
function memorySettings(){const content=$('#panel-content');content.insertAdjacentHTML('beforeend',`<details><summary>Optional Scripture memory</summary><p>Rehearse half a card at a time, as in Lantern Road. Gifts and exploration stay relaxed.</p><label for="recall-mode">Recall controls</label><select id="recall-mode"><option value="phrases">Select phrases</option><option value="choose">Choose a completion</option><option value="type">Type the missing half</option></select><label for="recall-scope">What to rehearse</label><select id="recall-scope"><option value="excerpts">Verse text / successive excerpts</option><option value="summary">Short card headlines</option></select><label for="recall-level">Difficulty</label><select id="recall-level"><option value="easy">Elementary · one short verse</option><option value="hard">Harder · longer passages and more choices</option></select><div class="row"><button id="open-practice">Choose a discovered card</button></div></details>`);for(const [id,key]of [['recall-mode','mode'],['recall-scope','scope'],['recall-level','difficulty']]){$('#'+id).value=state.recall[key];$('#'+id).onchange=function preference(e){state.recall[key]=e.target.value;save();/* Code by Daniel using ChatGPT November 11, 2026 */};}$('#open-practice').onclick=recallLibrary;/* Code by Daniel using ChatGPT November 11, 2026 *//* Code by Daniel using ChatGPT November 12, 2026 */}
// Keep going after a rehearsal: the card's other verses or other half, or another discovered card,
