 const count=function(i){return state.recalls[recallKey(c,ex.scope,i)]||0;};
 const verses=units.map(function(u,i){return i;}).filter(function(i){return i!==ex.index&&!(done.has(c.id+':'+i+':a')&&done.has(c.id+':'+i+':b'));}).sort(function(a,b){return count(a)-count(b);});
