 const others=cards.filter(function(o){return o.id!==c.id&&known(o)&&!done.has(o.id+':any');}).sort(function(a,b){return (state.recalls[recallKey(a,ex.scope,0)]||0)-(state.recalls[recallKey(b,ex.scope,0)]||0)||Math.random()-.5;});
